    /// <summary>取值工具</summary>
    internal static class ConfigValue
    {
        public static object ToObject(JsonElement cell)
        {
            switch (cell.ValueKind)
            {
                case JsonValueKind.Number:
                    int number;
                    return cell.TryGetInt32(out number) ? (object)number : cell.GetDouble();
                case JsonValueKind.String:
                    return cell.GetString();
                case JsonValueKind.True:
                    return true;
                case JsonValueKind.False:
                    return false;
                case JsonValueKind.Array:
                    var list = new List<object>();
                    foreach (var item in cell.EnumerateArray()) list.Add(ToObject(item));
                    return list;
                default:
                    return null;
            }
        }

        public static int ToInt(object value)
        {
            if (value == null) return 0;
            if (value is int) return (int)value;
            if (value is long) return (int)(long)value;
            if (value is bool) return (bool)value ? 1 : 0;
            if (value is double) return (int)(double)value;
            if (value is float) return (int)(float)value;
            double number;
            return double.TryParse(value.ToString(), out number) ? (int)number : 0;
        }

        public static long ToLong(object value)
        {
            if (value == null) return 0;
            if (value is long) return (long)value;
            if (value is int) return (int)value;
            return (long)ToDouble(value);
        }

        public static double ToDouble(object value)
        {
            if (value == null) return 0;
            if (value is double) return (double)value;
            if (value is float) return (float)value;
            if (value is int) return (int)value;
            if (value is long) return (long)value;
            double number;
            return double.TryParse(value.ToString(), out number) ? number : 0;
        }

        public static bool ToBool(object value)
        {
            if (value is bool) return (bool)value;
            return ToInt(value) != 0;
        }

        public static string ToStr(object value)
        {
            return value == null ? string.Empty : value.ToString();
        }

        public static int ToInt(JsonElement cell) { return ToInt(ToObject(cell)); }

        public static long ToLong(JsonElement cell) { return ToLong(ToObject(cell)); }

        public static double ToDouble(JsonElement cell) { return ToDouble(ToObject(cell)); }

        public static bool ToBool(JsonElement cell) { return ToBool(ToObject(cell)); }

        public static string ToStr(JsonElement cell) { return ToStr(ToObject(cell)); }

        public static List<int> ToIntList(object value)
        {
            var result = new List<int>();
            var items = value as List<object>;
            if (items == null) return result;
            foreach (var item in items) result.Add(ToInt(item));
            return result;
        }

        public static List<string> ToStrList(object value)
        {
            var result = new List<string>();
            var items = value as List<object>;
            if (items == null) return result;
            foreach (var item in items) result.Add(ToStr(item));
            return result;
        }

        public static List<bool> ToBoolList(object value)
        {
            var result = new List<bool>();
            var items = value as List<object>;
            if (items == null) return result;
            foreach (var item in items) result.Add(ToBool(item));
            return result;
        }

        public static List<object> ToObjectList(JsonElement cell)
        {
            var list = new List<object>();
            if (cell.ValueKind != JsonValueKind.Array) return list;
            foreach (var item in cell.EnumerateArray()) list.Add(ToObject(item));
            return list;
        }

        public static int[] ToIntArray(JsonElement cell)
        {
            var values = new List<int>();
            if (cell.ValueKind != JsonValueKind.Array) return values.ToArray();
            foreach (var item in cell.EnumerateArray()) values.Add(ToInt(item));
            return values.ToArray();
        }

        /// <summary>ids 已升序时返回 null，否则返回按 id 排序的行号表</summary>
        public static int[] BuildOrder(int[] ids)
        {
            for (int i = 1; i < ids.Length; i++)
            {
                if (ids[i] <= ids[i - 1])
                {
                    var order = new int[ids.Length];
                    for (int j = 0; j < order.Length; j++) order[j] = j;
                    Array.Sort(order, (a, b) => ids[a].CompareTo(ids[b]));
                    return order;
                }
            }

            return null;
        }

        /// <summary>二分查找主键所在行，找不到返回 -1</summary>
        public static int IndexOfKey(int[] ids, int[] order, int id)
        {
            int low = 0;
            int high = ids.Length - 1;

            while (low <= high)
            {
                int mid = (low + high) >> 1;
                int row = order == null ? mid : order[mid];
                int value = ids[row];

                if (value == id) return row;
                if (value < id) low = mid + 1; else high = mid - 1;
            }

            return -1;
        }
    }
